conn = sqlite3.connect('view.sqlite')
conn.row_factory = sqlite3.Row

# op-01: services that depend directly on redis-west
q1 = """
SELECT DISTINCT sd.service_id
FROM service_dependencies sd
JOIN resources r ON sd.resource_id = r.id
WHERE r.id = 'resource:redis-west'
ORDER BY sd.service_id
"""
print("OP-01:", [r[0] for r in conn.execute(q1)])

# op-02: capabilities for those services
q2 = """
SELECT DISTINCT sc.capability_id
FROM service_dependencies sd
JOIN resources r ON sd.resource_id = r.id
JOIN service_capabilities sc ON sc.service_id = sd.service_id
WHERE r.id = 'resource:redis-west'
ORDER BY sc.capability_id
"""
print("OP-02:", [r[0] for r in conn.execute(q2)])

# op-03: teams owning redis-west services
q3 = """
