import sqlite3
conn = sqlite3.connect('view.sqlite')

print("Environments:", [dict(zip(['id','name','evidence'], r)) for r in conn.execute("SELECT * FROM environments")])

print("\nService deployments:", [dict(zip(['relation_id','service_id','environment_id','evidence'], r)) for r in conn.execute("SELECT * FROM service_deployments")])

# op-05: capabilities without fallback
q5 = """
SELECT DISTINCT sc.capability_id
FROM service_dependencies sd
JOIN resources r ON sd.resource_id = r.id
JOIN service_capabilities sc ON sc.service_id = sd.service_id
LEFT JOIN runbook_capability_coverage rcc ON rcc.capability_id = sc.capability_id
WHERE r.id = 'resource:redis-west'
  AND rcc.capability_id IS NULL
ORDER BY sc.capability_id
"""
print("\nOP-05:", [r[0] for r in conn.execute(q5)])

# op-06: production environments
q6 = """
SELECT DISTINCT e.id
FROM service_dependencies sd
JOIN resources r ON sd.resource_id = r.id
JOIN service_capabilities sc ON sc.service_id = sd.service_id
LEFT JOIN runbook_capability_coverage rcc ON rcc.capability_id = sc.capability_id
JOIN service_deployments sdep ON sdep.service_id = sd.service_id
JOIN environments e ON e.id = sdep.environment_id
WHERE r.id = 'resource:redis-west'
  AND rcc.capability_id IS NULL
  AND e.name LIKE '%production%'
ORDER BY e.id
"""
print("OP-06 (with production in name):", [r[0] for r in conn.execute(q6)])

# Try all environments for affected services
q6b = """
SELECT DISTINCT e.id, e.name
FROM service_dependencies sd
JOIN resources r ON sd.resource_id = r.id
JOIN service_capabilities sc ON sc.service_id = sd.service_id
LEFT JOIN runbook_capability_coverage rcc ON rcc.capability_id = sc.capability_id
JOIN service_deployments sdep ON sdep.service_id = sd.service_id
JOIN environments e ON e.id = sdep.environment_id
WHERE r.id = 'resource:redis-west'
  AND rcc.capability_id IS NULL
ORDER BY e.id
"""
print("OP-06 (all envs for affected):", [r for r in conn.execute(q6b)])

# op-07: path from redis-west to team:commerce through dependent service
# redis-west -> services (notifications, purchase) -> teams
# team:commerce owns one of these services?
print("\nOwnerships for redis-west services:")
for r in conn.execute("""
SELECT so.service_id, so.team_id, t.name
FROM service_dependencies sd
JOIN service_ownerships so ON so.service_id = sd.service_id
JOIN teams t ON t.id = so.team_id
WHERE sd.resource_id = 'resource:redis-west'
"""):
    print(r)

# Check if there's a path through dependent services - maybe service dependencies between services?
print("\nAll service_dependencies:")
for r in conn.execute("SELECT * FROM service_dependencies"):
    print(r)

